    private static void stubReads(StreamSourceChannel channel, Object... results) throws IOException {
        AtomicInteger index = new AtomicInteger();
        when(channel.read(any(ByteBuffer.class))).thenAnswer(invocation -> {
            int current = index.getAndIncrement();
            if (current >= results.length) {
                throw new AssertionError("Unexpected additional read invocation");
            }
            Object result = results[current];
            if (result instanceof Integer) {
                return result;
            }
            if (result instanceof IOException) {
                throw (IOException) result;
            }
            byte[] bytes = ((String) result).getBytes(StandardCharsets.ISO_8859_1);
            ByteBuffer buffer = invocation.getArgument(0);
            buffer.put(bytes);
            return bytes.length;
        });
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(Object target, String name) throws Exception {
        Field field = findField(target.getClass(), name);
        field.setAccessible(true);
        return (T) field.get(target);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = findField(target.getClass(), name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Field findField(Class<?> type, String name) throws NoSuchFieldException {
        Class<?> current = type;
        while (current != null) {
            try {
                return current.getDeclaredField(name);
            } catch (NoSuchFieldException ignored) {
                current = current.getSuperclass();
            }
        }
        throw new NoSuchFieldException(name);
    }

    private static final class CapturingExchangeCallback implements ClientCallback<ClientExchange> {
        private ClientExchange completed;
        private IOException failure;
        private int completedCount;
        private int failedCount;

        @Override
        public void completed(ClientExchange result) {
            completedCount++;
            completed = result;
        }

        @Override
        public void failed(IOException e) {
            failedCount++;
            failure = e;
        }
    }

    private static final class TrackingByteBufferPool implements ByteBufferPool {
        private final List<TrackingPooledByteBuffer> allocated = new ArrayList<>();

        @Override
        public PooledByteBuffer allocate() {
            TrackingPooledByteBuffer buffer = new TrackingPooledByteBuffer();
            allocated.add(buffer);
            return buffer;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return TrackingPooledByteBuffer.CAPACITY;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {
        private static final int CAPACITY = 8192;

        private final ByteBuffer buffer = ByteBuffer.allocate(CAPACITY);
        private boolean open = true;
        private int closeCount;

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closeCount++;
            open = false;
        }

        @Override
        public boolean isOpen() {
            return open;
        }
    }
