import org.xnio.ChannelListener;
import org.xnio.StreamConnection;
import org.xnio.XnioIoThread;
import org.xnio.XnioWorker;
import org.xnio.conduits.ConduitStreamSinkChannel;
import org.xnio.conduits.ConduitStreamSourceChannel;
import org.xnio.conduits.ReadReadyHandler;
import org.xnio.conduits.StreamSinkConduit;
import org.xnio.conduits.StreamSourceConduit;

/**
 * Tests for {@link SslConduit.SslReadReadyHandler#readReady()}.
 */
class SslConduitReadReadyTests {

    private static final int FLAG_READ_REQUIRES_WRITE = 1;
    private static final int FLAG_WRITE_REQUIRES_READ = 1 << 1;
    private static final int FLAG_READS_RESUMED = 1 << 2;
    private static final int FLAG_WRITES_RESUMED = 1 << 3;
    private static final int FLAG_DATA_TO_UNWRAP = 1 << 4;
    private static final int FLAG_ENGINE_INBOUND_SHUTDOWN = 1 << 7;
    private static final int FLAG_READ_CLOSED = 1 << 14;

    private StreamConnection delegate;
    private ConduitStreamSourceChannel delegateSourceChannel;
    private ConduitStreamSinkChannel delegateSinkChannel;
    private StreamSourceConduit sourceConduit;
    private StreamSinkConduit sinkConduit;
    private XnioIoThread ioThread;
    private XnioWorker worker;
    private SSLEngine engine;
    private ByteBufferPool bufferPool;
    private UndertowSslConnection connection;
    private SslConduit conduit;
    private boolean mocksReplayed;
    private PooledByteBuffer cleanupDataToUnwrap;
    private PooledByteBuffer cleanupUnwrappedData;
    private PooledByteBuffer cleanupWrappedData;

    @BeforeEach
    void setUp() {
        delegate = createMock(StreamConnection.class);
        ioThread = createMock(XnioIoThread.class);
        worker = createMock(XnioWorker.class);
        setDelegateThread(ioThread);
        sourceConduit = createNiceMock(StreamSourceConduit.class);
        sinkConduit = createNiceMock(StreamSinkConduit.class);
        delegateSourceChannel = new ConduitStreamSourceChannel(delegate, sourceConduit);
        delegateSinkChannel = new ConduitStreamSinkChannel(delegate, sinkConduit);
        reset(sourceConduit, sinkConduit);
        engine = createMock(SSLEngine.class);
        bufferPool = new DefaultByteBufferPool(false, 1024);

        expect(delegate.getIoThread()).andReturn(ioThread).anyTimes();
        expect(ioThread.getWorker()).andReturn(worker).anyTimes();
        expect(delegate.getSourceChannel()).andReturn(delegateSourceChannel).anyTimes();
        expect(delegate.getSinkChannel()).andReturn(delegateSinkChannel).anyTimes();
        expect(engine.getUseClientMode()).andReturn(true).anyTimes();
    }

    @AfterEach
    void tearDown() {
        if (mocksReplayed) {
            verify(delegate, sourceConduit, sinkConduit, ioThread, worker, engine);
        }
        closeIfOpen(cleanupDataToUnwrap);
        closeIfOpen(cleanupUnwrappedData);
        closeIfOpen(cleanupWrappedData);
        bufferPool.close();
    }

    @Test
    void readReadyDoesNothingWhenReadsAreNotResumed() {
        createConduit();
        setState(FLAG_WRITES_RESUMED);
        AtomicInteger listenerInvocations = new AtomicInteger();
        connection.getSourceChannel().setReadListener(channel -> listenerInvocations.incrementAndGet());

        readReadyHandler().readReady();

        assertEquals(0, listenerInvocations.get());
        assertEquals(FLAG_WRITES_RESUMED, state());
        assertFalse(conduit.isReadResumed());
    }

    @Test
    void readReadySuspendsReadsWhenNoReadListenerIsConfigured() {
        sourceConduit.suspendReads();
        expectLastCall().once();
        createConduit();
        setState(FLAG_READS_RESUMED);

        readReadyHandler().readReady();

        assertFalse(conduit.isReadResumed());
        assertEquals(0, state() & FLAG_READS_RESUMED);
    }

    @Test
    void readReadyInvokesConfiguredReadListener() {
        createConduit();
        setState(FLAG_READS_RESUMED);
        AtomicInteger listenerInvocations = new AtomicInteger();
        ChannelListener<ConduitStreamSourceChannel> listener =
                channel -> listenerInvocations.incrementAndGet();
        connection.getSourceChannel().setReadListener(listener);

        readReadyHandler().readReady();

        assertEquals(1, listenerInvocations.get());
        assertSame(listener, connection.getSourceChannel().getReadListener());
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void readReadyForwardsToDelegateHandlerWhenOneIsConfigured() {
        createConduit();
        ReadReadyHandler forwarded = createMock(ReadReadyHandler.class);
        forwarded.readReady();
        expectLastCall().once();
        replay(forwarded);

        conduit.setReadReadyHandler(forwarded);
        setState(FLAG_READS_RESUMED);
        connection.getSourceChannel().setReadListener(channel -> {
            throw new AssertionError("the connection listener must not be invoked when a delegate handler exists");
        });

        readReadyHandler().readReady();

        verify(forwarded);
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void unchangedDataToUnwrapDoesNotScheduleAnotherReadListenerRun() {
        createConduit();
        setState(FLAG_READS_RESUMED | FLAG_DATA_TO_UNWRAP);
        PooledByteBuffer data = pooledBufferWithBytes(1, 2, 3);
        cleanupDataToUnwrap = data;
        setField("dataToUnwrap", data);
        connection.getSourceChannel().setReadListener(channel -> {
            // Deliberately leave the buffer unchanged: this represents no forward progress.
        });

        readReadyHandler().readReady();

        assertEquals(3, data.getBuffer().remaining());
        assertSame(data, getField("dataToUnwrap"));
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void unchangedUnwrappedDataDoesNotScheduleAnotherReadListenerRun() {
        createConduit();
        setState(FLAG_READS_RESUMED);
        PooledByteBuffer data = pooledBufferWithBytes(4, 5, 6);
        cleanupUnwrappedData = data;
        setField("unwrappedData", data);
        connection.getSourceChannel().setReadListener(channel -> {
            // Deliberately leave the buffer unchanged: this represents no forward progress.
        });

        readReadyHandler().readReady();

        assertEquals(3, data.getBuffer().remaining());
        assertSame(data, getField("unwrappedData"));
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void consumingDataToUnwrapSchedulesAnotherReadListenerRun() {
        ioThread.execute(anyObject(Runnable.class));
        expectLastCall().once();
        createConduit();
        setState(FLAG_READS_RESUMED | FLAG_DATA_TO_UNWRAP);
        PooledByteBuffer data = pooledBufferWithBytes(7, 8, 9);
        cleanupDataToUnwrap = data;
        setField("dataToUnwrap", data);
        connection.getSourceChannel().setReadListener(channel -> data.getBuffer().get());

        readReadyHandler().readReady();

        assertEquals(2, data.getBuffer().remaining());
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void consumingUnwrappedDataSchedulesAnotherReadListenerRun() {
        ioThread.execute(anyObject(Runnable.class));
        expectLastCall().once();
        createConduit();
        setState(FLAG_READS_RESUMED);
        PooledByteBuffer data = pooledBufferWithBytes(10, 11, 12);
        cleanupUnwrappedData = data;
        setField("unwrappedData", data);
        connection.getSourceChannel().setReadListener(channel -> data.getBuffer().get());

        readReadyHandler().readReady();

        assertEquals(2, data.getBuffer().remaining());
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void readRequiresWriteWithPendingWrappedDataPreventsScheduling() {
        createConduit();
        setState(FLAG_READS_RESUMED | FLAG_READ_REQUIRES_WRITE);
        PooledByteBuffer unwrapped = pooledBufferWithBytes(13, 14, 15);
        PooledByteBuffer wrapped = pooledBufferWithBytes(16);
        cleanupUnwrappedData = unwrapped;
        cleanupWrappedData = wrapped;
        setField("unwrappedData", unwrapped);
        setField("wrappedData", wrapped);
        connection.getSourceChannel().setReadListener(channel -> unwrapped.getBuffer().get());

        readReadyHandler().readReady();

        assertEquals(2, unwrapped.getBuffer().remaining());
        assertSame(wrapped, getField("wrappedData"));
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void outstandingTasksPreventSchedulingAnotherReadListenerRun() {
        createConduit();
        setState(FLAG_READS_RESUMED);
        setField("outstandingTasks", 1);
        PooledByteBuffer data = pooledBufferWithBytes(22, 23, 24);
        cleanupUnwrappedData = data;
        setField("unwrappedData", data);
        connection.getSourceChannel().setReadListener(channel -> data.getBuffer().get());

        readReadyHandler().readReady();

        assertEquals(2, data.getBuffer().remaining());
        assertEquals(1, getField("outstandingTasks"));
        assertTrue(conduit.isReadResumed());
    }

    @Test
    void readClosedClosesUnwrappedAndPendingBuffersAndClearsReferences() {
        createConduit();
        setState(FLAG_READS_RESUMED | FLAG_DATA_TO_UNWRAP | FLAG_READ_CLOSED);
        PooledByteBuffer dataToUnwrap = pooledBufferWithBytes(17, 18);
        PooledByteBuffer unwrapped = pooledBufferWithBytes(19, 20, 21);
        cleanupDataToUnwrap = dataToUnwrap;
        cleanupUnwrappedData = unwrapped;
        setField("dataToUnwrap", dataToUnwrap);
        setField("unwrappedData", unwrapped);
        connection.getSourceChannel().setReadListener(channel -> {
            // Keep both buffers available for the read-closed cleanup branch.
        });

        readReadyHandler().readReady();

        assertFalse(dataToUnwrap.isOpen());
        assertFalse(unwrapped.isOpen());
        assertNull(getField("dataToUnwrap"));
        assertNull(getField("unwrappedData"));
    }

    @Test
    void writeRequiresReadRunsHandshakeWhenWritesAreResumed() throws Exception {
        expect(sourceConduit.read(anyObject(ByteBuffer.class))).andReturn(0).once();
        expect(engine.getHandshakeStatus()).andReturn(HandshakeStatus.NEED_UNWRAP).anyTimes();
        expect(engine.unwrap(anyObject(ByteBuffer.class), anyObject(ByteBuffer[].class), eq(0), eq(1)))
                .andReturn(new SSLEngineResult(Status.OK, HandshakeStatus.NEED_WRAP, 0, 0))
                .once();
        expect(engine.wrap(eq(SslConduit.EMPTY_BUFFER), anyObject(ByteBuffer.class)))
                .andReturn(new SSLEngineResult(Status.OK, HandshakeStatus.NEED_UNWRAP, 0, 0))
                .once();
        sourceConduit.suspendReads();
        expectLastCall().once();
        sinkConduit.suspendWrites();
        expectLastCall().once();
        sourceConduit.resumeReads();
        expectLastCall().once();
        ioThread.execute(anyObject(Runnable.class));
        expectLastCall().once();
        createConduit();
        setState(FLAG_WRITE_REQUIRES_READ | FLAG_WRITES_RESUMED);

        readReadyHandler().readReady();

        assertTrue((state() & FLAG_WRITE_REQUIRES_READ) != 0);
        assertTrue((state() & FLAG_WRITES_RESUMED) != 0);
        assertFalse(conduit.isReadResumed());
    }

    @Test
    void writeRequiresReadDoesNotRunHandshakeWhenEngineInboundIsShutdown() {
        createConduit();
        setState(FLAG_WRITE_REQUIRES_READ | FLAG_WRITES_RESUMED | FLAG_ENGINE_INBOUND_SHUTDOWN);

        readReadyHandler().readReady();

        assertEquals(FLAG_WRITE_REQUIRES_READ | FLAG_WRITES_RESUMED | FLAG_ENGINE_INBOUND_SHUTDOWN, state());
    }

    private void setDelegateThread(XnioIoThread thread) {
        try {
            Field field = org.xnio.Connection.class.getDeclaredField("thread");
            field.setAccessible(true);
            field.set(delegate, thread);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to configure delegate thread", e);
        }
    }

    private void createConduit() {
        replay(delegate, sourceConduit, sinkConduit, ioThread, worker, engine);
        mocksReplayed = true;
        connection = new UndertowSslConnection(delegate, engine, bufferPool, worker);
        conduit = connection.getSslConduit();
        conduit.setReadReadyHandler(null);
    }

    private PooledByteBuffer pooledBufferWithBytes(int... bytes) {
        byte[] values = new byte[bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            values[i] = (byte) bytes[i];
        }
        PooledByteBuffer buffer = bufferPool.allocate();
        buffer.getBuffer().put(values);
        buffer.getBuffer().flip();
        return buffer;
    }

    private ReadReadyHandler readReadyHandler() {
        Object handler = getField("readReadyHandler");
        assertNotNull(handler);
        return (ReadReadyHandler) handler;
    }

    private int state() {
        return (Integer) getField("state");
    }

    private void setState(int state) {
        setField("state", state);
    }

    private Object getField(String name) {
        try {
            Field field = SslConduit.class.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(conduit);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to read SslConduit field " + name, e);
        }
    }

    private void setField(String name, Object value) {
        try {
            Field field = SslConduit.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(conduit, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to write SslConduit field " + name, e);
        }
    }

    private static void closeIfOpen(PooledByteBuffer buffer) {
        if (buffer != null && buffer.isOpen()) {
            buffer.close();
        }
    }
}

