    @Test
    void acceptReturnsNullWhenThereIsNoPendingConnection() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, null);

        UndertowSslConnection result = channel.accept();

        assertNull(result);
