        verify(tcpServer);
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptPropagatesIOExceptionFromTcpServerWithoutCreatingAnSslConnection() throws Exception {
        @SuppressWarnings({"rawtypes", "unchecked"})
