        ChannelListener.Setter acceptSetter = new ChannelListener.SimpleSetter();
        expect(tcpServer.getCloseSetter()).andReturn(closeSetter);
        expect(tcpServer.getAcceptSetter()).andReturn(acceptSetter);
        IOException failure = new IOException("tcp accept failed");
        expect(tcpServer.accept()).andThrow(failure);
