        UndertowXnioSsl ssl = new UndertowXnioSsl(null, OptionMap.EMPTY, sslContext);
        CapturingAcceptingSslChannel channel = new CapturingAcceptingSslChannel(ssl, tcpServer, OptionMap.EMPTY, null, false);

        IOException thrown = assertThrows(IOException.class, channel::accept);

