        OptionMap options = OptionMap.builder()
                .set(Options.SSL_USE_CLIENT_MODE, true)
                .set(Options.SSL_ENABLE_SESSION_CREATION, false)
                .set(UndertowOptions.SSL_USER_CIPHER_SUITES_ORDER, true)
                .getMap();
        SSLEngine engine = sslContext.createSSLEngine(PEER_HOST, PEER_PORT);
        SSLParameters parameters = engine.getSSLParameters();
        parameters.setUseCipherSuitesOrder(false);
