                case "getCloseSetter":
                    return closeSetter;
                case "resumeWrites":
                    resumeWritesCalls++;
                    return null;
                case "suspendWrites":
                    suspendWritesCalls++;
                    return null;
                case "shutdownWrites":
                    shutdownWritesCalls++;
                    return null;
                case "close":
