    private static CompletableFuture<AlpnOpenListener.SelectedAlpn> completedSelection(String protocol) throws Exception {
        CompletableFuture<AlpnOpenListener.SelectedAlpn> selection = new CompletableFuture<>();
        SSLEngine engine = SSLContext.getDefault().createSSLEngine();
        selection.complete(new AlpnOpenListener.SelectedAlpn(engine, new FixedAlpnProvider(protocol)));
        return selection;
    }

    @SuppressWarnings("unchecked")
    private static ChannelListener<StreamSourceChannel> newReadListener(AlpnOpenListener openListener,
            StreamConnection connection, CompletableFuture<AlpnOpenListener.SelectedAlpn> selection)
            throws Exception {
        Class<?> listenerClass = Class.forName(AlpnOpenListener.class.getName() + "$AlpnConnectionListener");
        Constructor<?> constructor = listenerClass.getDeclaredConstructor(AlpnOpenListener.class,
                StreamConnection.class, CompletableFuture.class);
        constructor.setAccessible(true);
        return (ChannelListener<StreamSourceChannel>) constructor.newInstance(openListener, connection, selection);
    }

