        for (Harness harness : harnesses) {
            try {
                harness.connection.setExtraBytes(null);
                harness.connection.close();
            } catch (Throwable ignored) {
                // best effort cleanup, the assertions have already been made
            }
        }
        harnesses.clear();
    }

