    @Test
    void readShutdownWithoutExtraBytesClosesConnectionAndSuspendsReads() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        source.setReadShutdown(true);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertFalse(harness.streamConnection.isOpen(), "the connection must be closed when the source is shut down");
        assertEquals(1, source.suspendCount, "reads must be suspended");
        assertEquals(0, source.readCount, "no read may be attempted on a closing connection");
        assertEquals(0, pool.allocateCount, "no buffer may be allocated on a closing connection");
        assertTrue(handled.isEmpty(), "no exchange may be created on a closing connection");
        assertNull(harness.connection.getExtraBytes());
    }

