    // helpers
    // ------------------------------------------------------------------

    private Harness harness(final TestSourceConduit source, final TestSinkConduit sink, final OptionMap options,
            final ByteBufferPool pool, final List<HttpServerExchange> handled) {
        final TestStreamConnection streamConnection = new TestStreamConnection(ioThread, source, sink);
        final HttpHandler handler = new HttpHandler() {
            @Override
            public void handleRequest(final HttpServerExchange exchange) {
                handled.add(exchange);
                // keep the exchange "in progress" so that the listener is not reset by the exchange completion
                exchange.dispatch(NO_OP_EXECUTOR, new Runnable() {
                    @Override
                    public void run() {
                    }
                });
            }
        };
        final HttpServerConnection connection = new HttpServerConnection(streamConnection, pool, handler, options, 8192, null);
        final HttpReadListener listener = new HttpReadListener(connection, RequestParser.instance(options), null);
        connection.setReadListener(listener);
        Harness harness = new Harness(streamConnection, connection, listener);
        harnesses.add(harness);
        return harness;
    }

    private static byte[] bytes(final String value) {
        return value.getBytes(StandardCharsets.US_ASCII);
    }

    private static String remaining(final ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        byte[] data = new byte[copy.remaining()];
        copy.get(data);
        return new String(data, StandardCharsets.US_ASCII);
    }

    private static ParseTimeoutUpdater parseTimeoutUpdater(final HttpReadListener listener) throws Exception {
        Field field = HttpReadListener.class.getDeclaredField("parseTimeoutUpdater");
        field.setAccessible(true);
        return (ParseTimeoutUpdater) field.get(listener);
    }

    private static boolean isParsing(final ParseTimeoutUpdater updater) throws Exception {
        Field field = ParseTimeoutUpdater.class.getDeclaredField("parsing");
        field.setAccessible(true);
        return (Boolean) field.get(updater);
    }

    private static final class Harness {
        private final TestStreamConnection streamConnection;
        private final HttpServerConnection connection;
        private final HttpReadListener listener;

        private Harness(final TestStreamConnection streamConnection, final HttpServerConnection connection,
                final HttpReadListener listener) {
            this.streamConnection = streamConnection;
            this.connection = connection;
            this.listener = listener;
        }
    }

    /**
     * A {@link PooledByteBuffer} that records if it has been released.
     */
    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean closed;

        private TrackingPooledByteBuffer(final ByteBuffer buffer) {
            this.buffer = buffer;
        }

        private TrackingPooledByteBuffer(final byte[] data) {
            this(ByteBuffer.wrap(data));
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closed = true;
        }

        @Override
