    void handleEventCompactsBufferedDataAndReadsIntoItForReadNotification() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.read(buffer -> {
            assertEquals(3, buffer.position(), "the leftover data must be kept at the start of the buffer");
            assertEquals(CAPACITY - 3, buffer.remaining(), "the read is performed after the leftover data");
            return 0;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals(0, fixture.pool.allocated.size(), "the existing buffer is reused");
        assertEquals(1L, fixture.source.count("read:0"));
        assertEquals(0L, fixture.sink.countPrefix("write:"));
        assertEquals(1L, fixture.sink.count("resumeWrites"), "pending data means writes are resumed");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.source.count("suspendReads"));
        assertFalse(pooledBuffer.isClosed(), "a partially filled buffer must be kept for the next event");
        assertEquals("abc", drain(pooledBuffer.getBuffer()));
        assertEquals(0, pooledBuffer.getBuffer().position());
        assertEquals(3, pooledBuffer.getBuffer().limit());
    }

    @Test
    void handleEventKeepsBufferedDataWhenSinkWriteReturnsZero() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.sink.count("write:0"), "the sink is written to once and reports back pressure");
        assertEquals(1L, fixture.sink.count("resumeWrites"), "writes are resumed as data is still pending");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.sink.count("suspendWrites"));
        assertFalse(pooledBuffer.isClosed());
        assertEquals("abc", drain(pooledBuffer.getBuffer()), "the unwritten data must survive the event");
    }

    @Test
    void handleEventDoesNotResumeChannelsThatAreAlreadyResumed() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        fixture.sink.writeResumed = true;
        fixture.source.readResumed = true;
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.sink.count("isWriteResumed"));
        assertEquals(0L, fixture.sink.count("resumeWrites"), "already resumed writes must not be resumed again");
        assertEquals(1L, fixture.source.count("isReadResumed"));
        assertEquals(0L, fixture.source.count("resumeReads"), "already resumed reads must not be resumed again");
        assertFalse(pooledBuffer.isClosed());
    }

    @Test
    void handleEventSuspendsReadsWhenBufferIsCompletelyFull() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "0123456789abcdef");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.source.count("suspendReads"), "a completely full buffer suspends reads");
        assertEquals(0L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.source.countPrefix("read:"), "there is no room left to read into");
        assertEquals(1L, fixture.sink.count("resumeWrites"));
        assertFalse(pooledBuffer.isClosed());
        assertEquals(CAPACITY, pooledBuffer.getBuffer().remaining());
    }

    @Test
    void handleEventWritesRemainingDataBeforeCompletingWhenSourceIsDone() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "xyz");
        Fixture fixture = new Fixture().sourceDone(true).pooledBuffer(pooledBuffer);
        ByteArrayOutputStream written = new ByteArrayOutputStream();
        fixture.write(buffer -> {
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            written.write(data, 0, data.length);
            return data.length;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals("xyz", new String(written.toByteArray(), StandardCharsets.UTF_8),
                "the buffered data must be flushed before completing");
        assertEquals(0L, fixture.source.countPrefix("read:"), "a finished source must not be read again");
        assertEquals(1L, fixture.source.count("suspendReads"));
        assertEquals(1L, fixture.sink.count("suspendWrites"));
        assertTrue(pooledBuffer.isClosed(), "the fully written buffer is released");
    }

    @Test
    void handleEventWritesUntilBufferIsDrainedWithPartialWrites() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abcd");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        ByteArrayOutputStream written = new ByteArrayOutputStream();
        fixture.write(buffer -> {
            int chunk = Math.min(2, buffer.remaining());
            byte[] data = new byte[chunk];
            buffer.get(data);
            written.write(data, 0, chunk);
            return chunk;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(2L, fixture.sink.countPrefix("write:"), "the write loop continues while the sink accepts data");
        assertEquals("abcd", new String(written.toByteArray(), StandardCharsets.UTF_8));
        assertEquals(1L, fixture.sink.count("suspendWrites"), "an empty buffer suspends writes");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertTrue(pooledBuffer.isClosed());
    }

