    static final class RecordingSetter<T extends Channel> extends ChannelListener.SimpleSetter<T> {

        int setCount;

        @Override
        public void set(ChannelListener<? super T> listener) {
            setCount++;
            super.set(listener);
        }
    }

    static final class RecordingChannel implements InvocationHandler {

        final List<String> calls = new ArrayList<>();
        final RecordingSetter<Channel> readSetter = new RecordingSetter<>();
        final RecordingSetter<Channel> writeSetter = new RecordingSetter<>();
        final RecordingSetter<Channel> closeSetter = new RecordingSetter<>();

        boolean readResumed;
        boolean writeResumed;
        boolean open = true;
        ReadHandler readHandler = buffer -> 0;
        WriteHandler writeHandler = buffer -> {
            int remaining = buffer.remaining();
            buffer.position(buffer.limit());
            return remaining;
        };

        private final Map<List<Class<?>>, Object> proxies = new HashMap<>();

        Object proxy(Class<?>... interfaces) {
            List<Class<?>> key = List.of(interfaces);
            return proxies.computeIfAbsent(key,
                    ignored -> Proxy.newProxyInstance(RecordingChannel.class.getClassLoader(), interfaces, this));
        }

        void reset() {
            calls.clear();
        }

        long count(String call) {
            return calls.stream().filter(call::equals).count();
        }

        long countPrefix(String prefix) {
            return calls.stream().filter(call -> call.startsWith(prefix)).count();
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            String name = method.getName();
            switch (name) {
                case "getReadSetter":
                    calls.add("getReadSetter");
                    return readSetter;
                case "getWriteSetter":
                    calls.add("getWriteSetter");
                    return writeSetter;
                case "getCloseSetter":
                    calls.add("getCloseSetter");
                    return closeSetter;
                case "suspendReads":
                    calls.add("suspendReads");
                    readResumed = false;
                    return null;
                case "resumeReads":
                    calls.add("resumeReads");
                    readResumed = true;
                    return null;
                case "wakeupReads":
                    calls.add("wakeupReads");
                    return null;
                case "isReadResumed":
                    calls.add("isReadResumed");
                    return readResumed;
                case "suspendWrites":
                    calls.add("suspendWrites");
                    writeResumed = false;
                    return null;
                case "resumeWrites":
                    calls.add("resumeWrites");
                    writeResumed = true;
                    return null;
                case "wakeupWrites":
                    calls.add("wakeupWrites");
                    return null;
                case "isWriteResumed":
                    calls.add("isWriteResumed");
                    return writeResumed;
                case "read":
                    if (args != null && args.length == 1 && args[0] instanceof ByteBuffer) {
                        int read = readHandler.read((ByteBuffer) args[0]);
                        calls.add("read:" + read);
                        return read;
                    }
                    return defaultValue(method.getReturnType());
                case "write":
                    int written = writeHandler.write((ByteBuffer) args[0]);
                    calls.add("write:" + written);
                    return written;
                case "flush":
                    return Boolean.TRUE;
                case "isOpen":
                    return open;
                case "close":
                    calls.add("close");
                    open = false;
                    return null;
                case "toString":
                    return "RecordingChannel";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }

        private static Object defaultValue(Class<?> type) {
            if (type == boolean.class) {
                return Boolean.FALSE;
            } else if (type == byte.class) {
                return (byte) 0;
            } else if (type == short.class) {
                return (short) 0;
            } else if (type == int.class) {
                return 0;
            } else if (type == long.class) {
                return 0L;
            } else if (type == float.class) {
                return 0f;
            } else if (type == double.class) {
                return 0d;
            } else if (type == char.class) {
                return (char) 0;
            }
            return null;
        }
    }

    static final class FakePooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean open = true;
        private int closeCount;

        FakePooledBuffer(ByteBuffer buffer) {
            this.buffer = buffer;
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            open = false;
            closeCount++;
        }

        @Override
        public boolean isOpen() {
            return open;
        }

        boolean isClosed() {
            return !open;
        }

        int getCloseCount() {
            return closeCount;
        }
    }

    static final class FakePool implements ByteBufferPool {

        private final int capacity;
        final List<FakePooledBuffer> allocated = new ArrayList<>();

        FakePool(int capacity) {
            this.capacity = capacity;
        }

        @Override
        public PooledByteBuffer allocate() {
            FakePooledBuffer pooledBuffer = new FakePooledBuffer(ByteBuffer.allocate(capacity));
            allocated.add(pooledBuffer);
            return pooledBuffer;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return capacity;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static FakePooledBuffer bufferContaining(int capacity, String data) {
        ByteBuffer buffer = ByteBuffer.allocate(capacity);
        buffer.put(data.getBytes(StandardCharsets.UTF_8));
        buffer.flip();
        return new FakePooledBuffer(buffer);
    }

    private static String drain(ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        byte[] data = new byte[copy.remaining()];
        copy.get(data);
        return new String(data, StandardCharsets.UTF_8);
    }
